<?php require_once __DIR__ . '/lib/accounts.php'; verify_csrf(); $password = $_POST['password'] ?? ''; if ($_SERVER['REQUEST_METHOD'] !== 'POST' || !is_string($password) || strlen($password) < 9 || !preg_match('/[A-Za-z]/', $password) || !preg_match('/\d/', $password) || !reset_password((string) ($_POST['token'] ?? ''), $password)) { flash('error', 'Link inválido, expirado ou senha fora dos requisitos.'); redirect('/recuperar-senha.php'); } flash('success', 'Senha atualizada. Entre com sua nova senha.'); redirect('/login.php');
